def fig(file, caption):
    _fig[0] += 1
    return (f'<figure><img src="figures/{file}" alt="그림 {_fig[0]}"><figcaption><b>그림 {_fig[0]}.</b> {caption}</figcaption></figure>')


def tbl(caption, header, rows, note=None, cls=''):
    _tab[0] += 1
    th = ''.join(f'<th>{h}</th>' for h in header)
    tr = ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in r) + '</tr>' for r in rows)
    n = f'<p class="tnote">{note}</p>' if note else ''
    return (f'<div class="tbl {cls}"><p class="tcap"><b>표 {_tab[0]}.</b> {caption}</p><table><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table>{n}</div>')


